package com.clothingstore;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/admin/products") @CrossOrigin(origins="${app.cors-origin}") public class AdminProductController { private final ProductRepository products; AdminProductController(ProductRepository products){this.products=products;} record ProductRequest(@NotBlank String name,@NotBlank String slug,@NotBlank String category,@NotNull @DecimalMin("0.01") BigDecimal price,@NotBlank String imageUrl,boolean active){} record ProductResponse(Long id,String name,String slug,String category,BigDecimal price,String imageUrl,boolean active){} private ProductResponse response(Product p){return new ProductResponse(p.getId(),p.getName(),p.getSlug(),p.getCategory(),p.getPrice(),p.getImageUrl(),true);} private void copy(ProductRequest r,Product p){p.setName(r.name());p.setSlug(r.slug());p.setCategory(r.category());p.setPrice(r.price());p.setImageUrl(r.imageUrl());p.setActive(r.active());} @GetMapping public List<ProductResponse> all(){return products.findAll().stream().map(this::response).toList();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public ProductResponse create(@RequestBody @Valid ProductRequest request){Product p=new Product();copy(request,p);return response(products.save(p));} @PutMapping("/{id}") public ProductResponse update(@PathVariable Long id,@RequestBody @Valid ProductRequest request){Product p=products.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));copy(request,p);return response(products.save(p));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(@PathVariable Long id){products.deleteById(id);} }
